INSERT INTO `ai_tool` (`id`, `tenant_id`, `tool_name`, `display_name`, `description`, `tool_type`, `config_json`, `status`, `create_dept`, `create_by`, `create_time`, `update_by`, `update_time`, `del_flag`, `attr1`, `attr2`, `attr3`, `attr4`) VALUES
(1, '000000', 'aps_schedule', '智能排产查询工具', '查询APS排产方案、拖期工单、瓶颈资源利用率、工单工序排程明细，支撑''哪些订单会拖期/瓶颈在哪''等决策问答', 'BUILTIN', '{}', '1', 100, 1, '2026-10-17 00:00:00', 1, '2026-10-17 00:00:00', '0', NULL, NULL, NULL, NULL),
(2, '000000', 'easyeda_engineering', '嘉立创EDA工程工具', '受控工程草稿、连接检查、打开、导出、DRC与私有归档，工具调用只派发任务', 'BUILTIN', '{}', '1', 100, 1, '2026-10-17 00:00:00', 1, '2026-10-17 00:00:00', '0', NULL, NULL, NULL, NULL),
(3, '000000', 'erp_inventory', '库存查询工具', '查询库存预警、出库趋势、库存金额分布、按仓库统计', 'BUILTIN', '{}', '1', 100, 1, '2026-10-17 00:00:00', 1, '2026-10-17 00:00:00', '0', NULL, NULL, NULL, NULL),
(4, '000000', 'erp_production', '生产查询工具', '查询在产工单、产能利用率、BOM展开、生产完成率', 'BUILTIN', '{}', '1', 100, 1, '2026-10-17 00:00:00', 1, '2026-10-17 00:00:00', '0', NULL, NULL, NULL, NULL),
(5, '000000', 'erp_purchase', '采购查询工具', '查询采购金额分布、供应商评估、在途订单、采购价格历史', 'BUILTIN', '{}', '1', 100, 1, '2026-10-17 00:00:00', 1, '2026-10-17 00:00:00', '0', NULL, NULL, NULL, NULL),
(6, '000000', 'erp_sales', '销售查询工具', '查询月度销售趋势、客户排行、退货统计、订单履行率', 'BUILTIN', '{}', '1', 100, 1, '2026-10-17 00:00:00', 1, '2026-10-17 00:00:00', '0', NULL, NULL, NULL, NULL),
(7, '000000', 'erp_shortage_risk', '缺料风险预测工具', '查询未来N天供应链缺料风险清单（MRP毛需求+库存+在途采购推演），返回物料/最早缺料日/缺口/建议动作，支撑''未来两周哪些物料会缺料/要不要催货''等供应链决策问答', 'BUILTIN', '{}', '1', 100, 1, '2026-10-17 00:00:00', 1, '2026-10-17 00:00:00', '0', NULL, NULL, NULL, NULL),
(8, '000000', 'execute_sql_query', '执行 SQL 查询', '执行 SELECT SQL 查询（必须包含 tenant_id 条件）', 'BUILTIN', '{}', '1', 100, 1, '2026-10-17 00:00:00', 1, '2026-10-17 00:00:00', '0', NULL, NULL, NULL, NULL),
(9, '000000', 'query_all_tables', '查询所有表', '查询数据库中所有可用的 ERP 业务表（从缓存获取）', 'BUILTIN', '{}', '1', 100, 1, '2026-10-17 00:00:00', 1, '2026-10-17 00:00:00', '0', NULL, NULL, NULL, NULL),
(10, '000000', 'query_knowledge_graph', '知识图谱查询', '查询当前知识库知识图谱的实体关系（1-2跳）或执行基于社区摘要的全局检索', 'BUILTIN', '{}', '1', 100, 1, '2026-10-17 00:00:00', 1, '2026-10-17 00:00:00', '0', NULL, NULL, NULL, NULL),
(11, '000000', 'query_table_schema', '查询表结构', '查询指定表的 CREATE TABLE DDL（优先从缓存获取）', 'BUILTIN', '{}', '1', 100, 1, '2026-10-17 00:00:00', 1, '2026-10-17 00:00:00', '0', NULL, NULL, NULL, NULL);
