-- Table: ai_ab_test
DROP TABLE IF EXISTS `ai_ab_test`;
CREATE TABLE `ai_ab_test` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户ID',
  `test_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '测试名称',
  `description` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '测试描述',
  `model_a_id` bigint(20) NOT NULL COMMENT '模型A的ID',
  `model_b_id` bigint(20) NOT NULL COMMENT '模型B的ID',
  `test_questions` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '测试问题列表（JSON数组）',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING' COMMENT '状态：PENDING/RUNNING/COMPLETED',
  `result_summary` text COLLATE utf8mb4_unicode_ci COMMENT '结果摘要（JSON）',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI A/B 测试';

-- Table: ai_ab_test_result
DROP TABLE IF EXISTS `ai_ab_test_result`;
CREATE TABLE `ai_ab_test_result` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户ID',
  `test_id` bigint(20) NOT NULL COMMENT '测试ID',
  `question` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '测试问题',
  `model_id` bigint(20) NOT NULL COMMENT '模型ID',
  `model_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型名称',
  `response` text COLLATE utf8mb4_unicode_ci COMMENT '模型回答',
  `token_usage` int(11) DEFAULT NULL COMMENT 'Token 用量',
  `latency_ms` int(11) DEFAULT NULL COMMENT '响应延迟（毫秒）',
  `score` int(11) DEFAULT NULL COMMENT '人工评分（1-5）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_test_id` (`test_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI A/B 测试结果';

-- Table: ai_config
DROP TABLE IF EXISTS `ai_config`;
CREATE TABLE `ai_config` (
  `config_group` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置分组: sql_safety/vector_store/web_search/flow/knowledge_graph',
  `config_value` json DEFAULT NULL COMMENT '配置值(分组内字段JSON)',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`config_group`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI运行参数配置(全局, 页面化替代nexus.ai yml运行参数)';

-- Table: ai_decision_action
DROP TABLE IF EXISTS `ai_decision_action`;
CREATE TABLE `ai_decision_action` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户编号',
  `run_id` bigint(20) NOT NULL COMMENT '决策运行ID',
  `action_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动作类型',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动作标题',
  `display_reason` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '展示理由',
  `target_biz_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目标业务类型',
  `target_biz_id` bigint(20) DEFAULT NULL COMMENT '目标业务ID',
  `target_biz_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目标业务编号',
  `payload_json` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '白名单动作参数JSON',
  `purchase_payload_version` tinyint(4) DEFAULT NULL COMMENT '采购动作载荷合同版本；NULL为旧合同，必须与run和冻结载荷校验',
  `risk_level` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动作风险等级',
  `approval_required` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Y' COMMENT '是否需要审批',
  `approval_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '审批状态',
  `execution_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '执行状态',
  `permission_code` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务权限码',
  `executor_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '执行器编码',
  `sequence_no` int(11) NOT NULL DEFAULT '0' COMMENT '执行顺序',
  `dependency_ids_json` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '依赖动作ID JSON',
  `idempotency_key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '幂等键',
  `approved_by` bigint(20) DEFAULT NULL COMMENT '审批人',
  `approved_at` datetime DEFAULT NULL COMMENT '审批时间',
  `approval_comment` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批意见',
  `result_biz_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结果业务类型',
  `result_biz_id` bigint(20) DEFAULT NULL COMMENT '结果业务ID',
  `result_biz_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结果业务编号',
  `result_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '执行结果JSON',
  `retry_count` int(11) NOT NULL DEFAULT '0' COMMENT '重试次数',
  `last_error_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最后错误码',
  `last_error_message` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最后脱敏错误',
  `started_at` datetime DEFAULT NULL COMMENT '执行开始时间',
  `finished_at` datetime DEFAULT NULL COMMENT '执行完成时间',
  `version` int(11) NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_decision_action_idempotency` (`tenant_id`,`idempotency_key`) USING BTREE,
  KEY `idx_decision_action_run` (`run_id`,`sequence_no`) USING BTREE,
  KEY `idx_decision_action_approval` (`tenant_id`,`approval_status`) USING BTREE,
  KEY `idx_decision_action_execution` (`tenant_id`,`execution_status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI工业决策动作';

-- Table: ai_decision_evidence
DROP TABLE IF EXISTS `ai_decision_evidence`;
CREATE TABLE `ai_decision_evidence` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户编号',
  `run_id` bigint(20) NOT NULL COMMENT '决策运行ID',
  `evidence_key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '运行内证据键',
  `source_domain` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ERP/MES/IOT/RAG/RULE/DERIVED',
  `source_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源类型',
  `source_id` bigint(20) DEFAULT NULL COMMENT '来源ID',
  `source_code` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源编号',
  `source_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源名称',
  `metric_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '指标编码',
  `metric_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '指标名称',
  `value_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '值类型',
  `metric_value` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '指标展示值',
  `unit` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `observed_at` datetime DEFAULT NULL COMMENT '观察时间',
  `data_version` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据版本',
  `confidence` decimal(5,4) DEFAULT NULL COMMENT '置信度',
  `verifiable` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Y' COMMENT '是否可验证',
  `normative` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'N' COMMENT '是否规范性证据',
  `derived_from_json` text COLLATE utf8mb4_unicode_ci COMMENT '派生来源证据键JSON',
  `display_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前端业务跳转路径',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_decision_evidence` (`run_id`,`evidence_key`) USING BTREE,
  KEY `idx_decision_evidence_source` (`tenant_id`,`source_type`,`source_id`) USING BTREE,
  KEY `idx_decision_evidence_run` (`run_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI工业决策证据';

-- Table: ai_decision_run
DROP TABLE IF EXISTS `ai_decision_run`;
CREATE TABLE `ai_decision_run` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户编号',
  `scene_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '场景编码',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型',
  `biz_id` bigint(20) DEFAULT NULL COMMENT '根业务ID',
  `biz_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '根业务编号',
  `parent_run_id` bigint(20) DEFAULT NULL COMMENT '父运行ID',
  `superseded_by_run_id` bigint(20) DEFAULT NULL COMMENT '替代运行ID',
  `trigger_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '触发类型',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '运行状态',
  `decision_contract_version` tinyint(4) DEFAULT NULL COMMENT '决策合同版本；NULL为旧合同，只有可信新版路径显式写2',
  `risk_score` decimal(8,2) DEFAULT NULL COMMENT '风险分数',
  `risk_level` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '风险等级',
  `confidence_level` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '置信度等级',
  `recommended_scenario_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '推荐方案编码',
  `input_snapshot_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '输入快照JSON',
  `input_snapshot_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '输入快照SHA-256',
  `snapshot_time` datetime DEFAULT NULL COMMENT '快照时间',
  `valid_until` datetime DEFAULT NULL COMMENT '审批有效截止时间',
  `score_config_json` text COLLATE utf8mb4_unicode_ci COMMENT '评分配置快照',
  `scenario_result_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '场景推演结果',
  `narrative_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '决策说明JSON',
  `result_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '完整决策结果JSON',
  `outcome_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '执行后结果JSON',
  `approval_context_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '可信审批执行人权限快照（禁止从Flow输入恢复）',
  `summary_mode` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MODEL/TEMPLATE_FALLBACK',
  `model_id` bigint(20) DEFAULT NULL COMMENT '模型ID',
  `model_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型名称快照',
  `prompt_version` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Prompt版本',
  `input_tokens` int(11) DEFAULT NULL COMMENT '输入Token',
  `output_tokens` int(11) DEFAULT NULL COMMENT '输出Token',
  `estimated_cost` decimal(18,6) DEFAULT NULL COMMENT '估算成本',
  `analysis_flow_instance_id` bigint(20) DEFAULT NULL COMMENT '分析Flow实例ID',
  `execution_flow_instance_id` bigint(20) DEFAULT NULL COMMENT '执行Flow实例ID',
  `error_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误码',
  `error_message` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '脱敏错误信息',
  `started_at` datetime DEFAULT NULL COMMENT '开始时间',
  `analysis_finished_at` datetime DEFAULT NULL COMMENT '分析完成时间',
  `finished_at` datetime DEFAULT NULL COMMENT '完成时间',
  `version` int(11) NOT NULL DEFAULT '0' COMMENT '乐观锁版本',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_decision_tenant_scene_status` (`tenant_id`,`scene_code`,`status`) USING BTREE,
  KEY `idx_decision_biz` (`tenant_id`,`biz_type`,`biz_id`) USING BTREE,
  KEY `idx_decision_create_time` (`tenant_id`,`create_time`) USING BTREE,
  KEY `idx_decision_parent` (`parent_run_id`) USING BTREE,
  KEY `idx_decision_analysis_flow` (`analysis_flow_instance_id`) USING BTREE,
  KEY `idx_decision_execution_flow` (`execution_flow_instance_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI工业决策运行';

-- Table: ai_engineering_artifact
DROP TABLE IF EXISTS `ai_engineering_artifact`;
CREATE TABLE `ai_engineering_artifact` (
  `artifact_id` bigint(20) NOT NULL COMMENT '产物编号',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '000000' COMMENT '租户编号',
  `user_id` bigint(20) NOT NULL COMMENT '产物所有者',
  `task_id` bigint(20) NOT NULL COMMENT '所属任务',
  `attempt` int(11) NOT NULL COMMENT '所属尝试编号',
  `artifact_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产物类型',
  `group_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '模型材质组',
  `relative_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '组内相对路径，区分大小写',
  `service` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '显式私有存储配置键',
  `oss_id` bigint(20) DEFAULT NULL COMMENT '内部私有对象编号',
  `object_key` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '服务端对象键，不对外输出',
  `sha256` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务端复核内容摘要',
  `size` bigint(20) NOT NULL COMMENT '真实字节数',
  `mime_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '验证后媒体类型',
  `original_filename` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '安全显示文件名',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'RESERVED' COMMENT '预留、确认或待清理状态',
  `cleanup_generation` bigint(20) NOT NULL DEFAULT '0' COMMENT '清理租约CAS代数，旧进程不得覆盖新清理者',
  `cleanup_expires_at` datetime DEFAULT NULL COMMENT '清理租约到期或失败后重试时间，过期CLEANING可恢复',
  `validation_json` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '服务端格式解析摘要',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建用户',
  `create_time` datetime DEFAULT NULL COMMENT '创建审计时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '修改用户',
  `update_time` datetime DEFAULT NULL COMMENT '修改审计时间',
  PRIMARY KEY (`artifact_id`),
  UNIQUE KEY `uk_engineering_artifact_path` (`tenant_id`,`task_id`,`attempt`,`artifact_type`,`relative_path`),
  KEY `idx_engineering_artifact_owner` (`tenant_id`,`user_id`,`task_id`,`status`),
  KEY `idx_engineering_artifact_cleanup` (`status`,`cleanup_expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI工程私有产物';

-- Table: ai_engineering_device
DROP TABLE IF EXISTS `ai_engineering_device`;
CREATE TABLE `ai_engineering_device` (
  `device_id` bigint(20) NOT NULL COMMENT '设备编号',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '000000' COMMENT '租户编号，保留前导零',
  `user_id` bigint(20) NOT NULL COMMENT '所有者用户编号',
  `device_name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '设备显示名称',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT '设备状态',
  `access_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '访问凭证摘要',
  `refresh_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '刷新凭证摘要',
  `generation` bigint(20) NOT NULL DEFAULT '1' COMMENT '凭证代数',
  `access_expires_at` datetime DEFAULT NULL COMMENT '访问凭证到期时间',
  `refresh_expires_at` datetime DEFAULT NULL COMMENT '刷新凭证到期时间',
  `credential_fingerprint` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '配对时认证状态内部摘要',
  `capabilities` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '设备实际能力与版本',
  `allowed_capabilities` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '配对允许能力集合',
  `last_heartbeat` datetime DEFAULT NULL COMMENT '最近心跳时间',
  `busy_task_id` bigint(20) DEFAULT NULL COMMENT '正在执行的任务',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建用户',
  `create_time` datetime DEFAULT NULL COMMENT '创建审计时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '修改用户',
  `update_time` datetime DEFAULT NULL COMMENT '修改审计时间',
  PRIMARY KEY (`device_id`),
  UNIQUE KEY `uk_engineering_device_access` (`access_hash`),
  UNIQUE KEY `uk_engineering_device_refresh` (`refresh_hash`),
  KEY `idx_engineering_device_owner` (`tenant_id`,`user_id`,`status`,`last_heartbeat`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI工程设备';

-- Table: ai_engineering_task
DROP TABLE IF EXISTS `ai_engineering_task`;
CREATE TABLE `ai_engineering_task` (
  `task_id` bigint(20) NOT NULL COMMENT '任务编号',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '000000' COMMENT '租户编号',
  `user_id` bigint(20) NOT NULL COMMENT '任务所有者',
  `device_id` bigint(20) NOT NULL COMMENT '指定执行设备',
  `session_id` bigint(20) DEFAULT NULL COMMENT '关联会话编号',
  `request_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '服务端聊天请求标识',
  `parent_task_id` bigint(20) DEFAULT NULL COMMENT '原任务编号',
  `action` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '受控动作',
  `idempotency_key` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '用户作用域幂等键',
  `request_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规范请求摘要',
  `request_json` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '有界结构化请求',
  `state` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务状态',
  `stage` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前阶段',
  `attempt` int(11) NOT NULL DEFAULT '0' COMMENT '领取尝试编号',
  `revision` bigint(20) NOT NULL DEFAULT '0' COMMENT '比较交换修订号',
  `lease_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '租约凭证摘要',
  `lease_expires_at` datetime DEFAULT NULL COMMENT '租约到期时间',
  `deadline_at` datetime DEFAULT NULL COMMENT '运行截止时间',
  `waiting_expires_at` datetime DEFAULT NULL COMMENT '等待设备截止时间',
  `cancel_requested` tinyint(1) NOT NULL DEFAULT '0' COMMENT '运行取消请求',
  `step_journal` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '有界步骤回执日志',
  `reserved_bytes` bigint(20) NOT NULL DEFAULT '0' COMMENT '已确认及预留字节总量',
  `reserved_files` int(11) NOT NULL DEFAULT '0' COMMENT '已确认及预留文件数量',
  `error_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '安全错误类别',
  `error_message` varchar(2048) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '中文安全错误摘要',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL COMMENT '修改时间',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建用户',
  `create_time` datetime DEFAULT NULL COMMENT '创建审计时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '修改用户',
  `update_time` datetime DEFAULT NULL COMMENT '修改审计时间',
  PRIMARY KEY (`task_id`),
  UNIQUE KEY `uk_engineering_task_owner` (`tenant_id`,`user_id`,`idempotency_key`),
  KEY `idx_engineering_task_device` (`tenant_id`,`user_id`,`device_id`,`state`),
  KEY `idx_engineering_task_expiry` (`state`,`lease_expires_at`,`waiting_expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI工程任务';

-- Table: ai_flow
DROP TABLE IF EXISTS `ai_flow`;
CREATE TABLE `ai_flow` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `flow_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程名称',
  `flow_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程标识(唯一, 定时/Webhook 引用)',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT' COMMENT '状态: DRAFT/PUBLISHED/OFFLINE',
  `version` int(11) NOT NULL DEFAULT '1' COMMENT '版本号(每次发布+1)',
  `config_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '画布配置(JSON: nodes+edges)',
  `trigger_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'MANUAL' COMMENT '触发方式: MANUAL/SCHEDULE (逗号分隔可多选)',
  `cron_expr` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '定时 Cron 表达式',
  `max_retry` int(11) NOT NULL DEFAULT '1' COMMENT '节点失败最大重试次数',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  `webhook_token` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Webhook访问令牌(空=不校验, flowKey本身即令牌)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_flow_key` (`flow_key`) USING BTREE,
  KEY `idx_tenant_status` (`tenant_id`,`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 流程定义';

-- Table: ai_flow_instance
DROP TABLE IF EXISTS `ai_flow_instance`;
CREATE TABLE `ai_flow_instance` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `flow_id` bigint(20) NOT NULL COMMENT '流程ID',
  `flow_version` int(11) NOT NULL DEFAULT '1' COMMENT '运行时的流程版本',
  `trigger_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL' COMMENT '触发方式: MANUAL/SCHEDULE',
  `trigger_by` bigint(20) DEFAULT NULL COMMENT '触发人(定时任务=流程创建人, 用于SSE通知)',
  `input_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '输入(JSON)',
  `output_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '输出(JSON, 末节点输出)',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'RUNNING' COMMENT '状态: RUNNING/SUCCEEDED/FAILED/STOPPED',
  `error_msg` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误信息',
  `duration_ms` bigint(20) DEFAULT NULL COMMENT '总耗时(毫秒)',
  `node_total` int(11) DEFAULT '0' COMMENT '节点总数',
  `node_success` int(11) DEFAULT '0' COMMENT '成功节点数',
  `node_failed` int(11) DEFAULT '0' COMMENT '失败节点数',
  `start_time` datetime DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  `config_snapshot` longtext COLLATE utf8mb4_unicode_ci COMMENT '启动时画布配置快照(续跑用)',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_flow_id` (`flow_id`,`id`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE,
  KEY `idx_create_time` (`create_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 流程运行实例';

-- Table: ai_flow_node_run
DROP TABLE IF EXISTS `ai_flow_node_run`;
CREATE TABLE `ai_flow_node_run` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `instance_id` bigint(20) NOT NULL COMMENT '实例ID',
  `flow_id` bigint(20) NOT NULL COMMENT '流程ID(冗余, 便于查询)',
  `node_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '画布节点ID(如 node_1)',
  `node_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '节点名称',
  `node_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点类型: LLM/AGENT/RAG/IF/CODE',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '状态: PENDING/RUNNING/SUCCEEDED/FAILED/SKIPPED',
  `input_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '输入(JSON, 渲染后的最终入参)',
  `output_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '输出(JSON)',
  `error_msg` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误信息',
  `retry_count` int(11) NOT NULL DEFAULT '0' COMMENT '已重试次数',
  `duration_ms` bigint(20) DEFAULT NULL COMMENT '耗时(毫秒)',
  `start_time` datetime DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  `batch_index` int(11) NOT NULL DEFAULT '0' COMMENT '循环批次索引(非循环执行=0)',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_instance_id` (`instance_id`) USING BTREE,
  KEY `idx_flow_id` (`flow_id`) USING BTREE,
  KEY `idx_instance_batch` (`instance_id`,`batch_index`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 流程节点运行记录';

-- Table: ai_flow_version
DROP TABLE IF EXISTS `ai_flow_version`;
CREATE TABLE `ai_flow_version` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `flow_id` bigint(20) NOT NULL COMMENT '流程ID',
  `flow_version` int(11) NOT NULL COMMENT '发布后的流程版本号',
  `flow_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流程名称(发布时快照)',
  `config_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '画布配置快照(JSON: nodes+edges)',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发布说明',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_flow_id_version` (`flow_id`,`flow_version`) USING BTREE,
  KEY `idx_create_time` (`create_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 流程版本快照';

-- Table: ai_image_record
DROP TABLE IF EXISTS `ai_image_record`;
CREATE TABLE `ai_image_record` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `user_id` bigint(20) NOT NULL COMMENT '生成用户ID',
  `prompt` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '提示词',
  `image_url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '图片URL（OSS）',
  `size` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '1280*1280' COMMENT '尺寸',
  `model_id` bigint(20) DEFAULT NULL COMMENT '使用的模型ID',
  `model_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型名称',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_create_time` (`create_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 文生图记录';

-- Table: ai_kg_community
DROP TABLE IF EXISTS `ai_kg_community`;
CREATE TABLE `ai_kg_community` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `graph_id` bigint(20) NOT NULL COMMENT '图谱ID',
  `community_level` int(11) DEFAULT '0' COMMENT '社区层级（v1 单层=0）',
  `parent_community_id` bigint(20) DEFAULT NULL COMMENT '父社区ID（v1 为空）',
  `community_index` int(11) DEFAULT NULL COMMENT '社区序号',
  `summary` text COLLATE utf8mb4_unicode_ci COMMENT '社区摘要（LLM 生成）',
  `summary_status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '摘要状态（0待生成 1生成中 2已完成 3失败）',
  `entity_count` int(11) DEFAULT '0' COMMENT '社区内实体数',
  `relation_count` int(11) DEFAULT '0' COMMENT '社区内关系数',
  `token_used` bigint(20) DEFAULT '0' COMMENT '摘要消耗token',
  `error_message` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误信息',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_graph_id` (`graph_id`) USING BTREE,
  KEY `idx_community_level` (`community_level`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 知识图谱社区';

-- Table: ai_kg_entity
DROP TABLE IF EXISTS `ai_kg_entity`;
CREATE TABLE `ai_kg_entity` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `graph_id` bigint(20) NOT NULL COMMENT '图谱ID',
  `entity_name` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实体名称',
  `entity_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实体类型',
  `description` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实体描述',
  `confidence` decimal(3,2) DEFAULT NULL COMMENT '置信度（0-1）',
  `source_chunk_id` bigint(20) DEFAULT NULL COMMENT '来源切片ID',
  `mention_count` int(11) DEFAULT '1' COMMENT '被提及次数（同名合并）',
  `community_id` bigint(20) DEFAULT NULL COMMENT '所属社区ID',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_graph_id` (`graph_id`) USING BTREE,
  KEY `idx_entity_name` (`entity_name`) USING BTREE,
  KEY `idx_entity_type` (`entity_type`) USING BTREE,
  KEY `idx_source_chunk` (`source_chunk_id`) USING BTREE,
  KEY `idx_community` (`community_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 知识图谱实体';

-- Table: ai_kg_relation
DROP TABLE IF EXISTS `ai_kg_relation`;
CREATE TABLE `ai_kg_relation` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `graph_id` bigint(20) NOT NULL COMMENT '图谱ID',
  `source_entity_id` bigint(20) NOT NULL COMMENT '头实体ID',
  `target_entity_id` bigint(20) NOT NULL COMMENT '尾实体ID',
  `relation_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关系类型',
  `description` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关系描述',
  `strength` int(11) DEFAULT NULL COMMENT '关系强度（0-10）',
  `confidence` decimal(3,2) DEFAULT NULL COMMENT '置信度（0-1）',
  `source_chunk_id` bigint(20) DEFAULT NULL COMMENT '来源切片ID',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_graph_id` (`graph_id`) USING BTREE,
  KEY `idx_source` (`source_entity_id`) USING BTREE,
  KEY `idx_target` (`target_entity_id`) USING BTREE,
  KEY `idx_source_chunk` (`source_chunk_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 知识图谱关系';

-- Table: ai_knowledge
DROP TABLE IF EXISTS `ai_knowledge`;
CREATE TABLE `ai_knowledge` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `knowledge_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '知识库名称',
  `description` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `embedding_model` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '使用的 Embedding 模型',
  `vector_store` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'milvus' COMMENT '向量存储类型',
  `vector_index_status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'READY' COMMENT '向量索引状态',
  `vector_index_progress` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '向量索引重建进度 0-100',
  `vector_index_error` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '向量索引错误信息',
  `vector_index_updated_time` datetime DEFAULT NULL COMMENT '向量索引最近完成时间',
  `status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '1' COMMENT '状态（1正常 0停用）',
  `separator` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT '#' COMMENT '知识分隔符',
  `overlap_char` int(11) DEFAULT '30' COMMENT '重叠字符数',
  `text_block_size` int(11) DEFAULT '500' COMMENT '文本块大小',
  `retrieve_limit` int(11) DEFAULT '5' COMMENT '检索条数',
  `similarity_threshold` double DEFAULT '0.5' COMMENT '相似度阈值',
  `enable_rerank` tinyint(1) DEFAULT '0' COMMENT '是否启用重排序（0否 1是）',
  `rerank_model` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '重排序模型名称',
  `enable_hybrid` tinyint(1) DEFAULT '0' COMMENT '是否启用混合检索（0否 1是）',
  `hybrid_alpha` double DEFAULT '0.5' COMMENT '混合检索权重（0=纯向量 1=纯关键词）',
  `system_prompt` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '系统提示词',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 知识库';

-- Table: ai_knowledge_chunk
DROP TABLE IF EXISTS `ai_knowledge_chunk`;
CREATE TABLE `ai_knowledge_chunk` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `document_id` bigint(20) NOT NULL COMMENT '文档ID',
  `knowledge_id` bigint(20) NOT NULL COMMENT '知识库ID',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '片段内容',
  `chunk_index` int(11) DEFAULT NULL COMMENT '片段序号',
  `vector_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '向量数据库中的ID',
  `extraction_status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '图谱抽取状态（0待处理 1处理中 2已完成 3失败）',
  `entity_count` int(11) DEFAULT '0' COMMENT '抽取实体数',
  `relation_count` int(11) DEFAULT '0' COMMENT '抽取关系数',
  `token_used` bigint(20) DEFAULT '0' COMMENT '抽取消耗token',
  `kg_error_message` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '抽取错误信息',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_knowledge_id` (`knowledge_id`) USING BTREE,
  KEY `idx_document_id` (`document_id`) USING BTREE,
  FULLTEXT KEY `ft_content` (`content`) /*!50100 WITH PARSER `ngram` */ 
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 知识库文档切片';

-- Table: ai_knowledge_document
DROP TABLE IF EXISTS `ai_knowledge_document`;
CREATE TABLE `ai_knowledge_document` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `knowledge_id` bigint(20) NOT NULL COMMENT '知识库ID',
  `file_name` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件名',
  `file_path` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OSS 文件路径',
  `file_size` bigint(20) DEFAULT NULL COMMENT '文件大小（字节）',
  `chunk_count` int(11) DEFAULT '0' COMMENT '分段数量',
  `status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '状态（0待解析 1解析中 2已完成 3失败）',
  `error_message` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误信息',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_knowledge_id` (`knowledge_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 知识库文档';

-- Table: ai_knowledge_graph
DROP TABLE IF EXISTS `ai_knowledge_graph`;
CREATE TABLE `ai_knowledge_graph` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `knowledge_id` bigint(20) NOT NULL COMMENT '知识库ID',
  `graph_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图谱名称',
  `graph_status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '状态（0未构建 1构建中 2已完成 3失败）',
  `node_count` int(11) DEFAULT '0' COMMENT '实体节点数',
  `relationship_count` int(11) DEFAULT '0' COMMENT '关系数',
  `community_count` int(11) DEFAULT '0' COMMENT '社区数',
  `model_id` bigint(20) DEFAULT NULL COMMENT '抽取用的LLM模型ID',
  `entity_types` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实体类型（逗号分隔）',
  `relation_types` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关系类型（逗号分隔）',
  `config` text COLLATE utf8mb4_unicode_ci COMMENT '图谱配置（JSON）',
  `error_message` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误信息',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_knowledge_id` (`knowledge_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 知识图谱实例';

-- Table: ai_mcp_market
DROP TABLE IF EXISTS `ai_mcp_market`;
CREATE TABLE `ai_mcp_market` (
  `id` bigint(20) NOT NULL COMMENT '主键',
