  `url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '市场URL（返回工具列表JSON）',
  `description` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `auth_config` text COLLATE utf8mb4_unicode_ci COMMENT '认证配置（JSON）',
