  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI MCP 市场源';

-- Table: ai_mcp_market_tool
DROP TABLE IF EXISTS `ai_mcp_market_tool`;
CREATE TABLE `ai_mcp_market_tool` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `market_id` bigint(20) NOT NULL COMMENT '市场ID',
  `tool_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工具名称',
  `tool_description` text COLLATE utf8mb4_unicode_ci COMMENT '工具描述',
  `tool_version` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工具版本',
  `tool_metadata` text COLLATE utf8mb4_unicode_ci COMMENT '工具元数据JSON（含 command/args/baseUrl 等）',
  `is_loaded` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '是否已加载到本地ai_tool（1是 0否）',
  `local_tool_id` bigint(20) DEFAULT NULL COMMENT '关联 ai_tool.id',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_market_id` (`market_id`) USING BTREE,
  KEY `idx_tool_name` (`tool_name`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI MCP 市场工具';

-- Table: ai_message
DROP TABLE IF EXISTS `ai_message`;
CREATE TABLE `ai_message` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `session_id` bigint(20) NOT NULL COMMENT '会话ID',
  `role` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色: USER/ASSISTANT/SYSTEM',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息内容',
  `token_usage` bigint(20) DEFAULT NULL COMMENT 'Token 消耗',
  `feedback` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户反馈: LIKE/DISLIKE',
  `feedback_content` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '反馈内容',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  `model_id` bigint(20) DEFAULT NULL COMMENT '使用的模型ID',
  `input_tokens` int(11) DEFAULT NULL COMMENT '输入 Token 数',
  `output_tokens` int(11) DEFAULT NULL COMMENT '输出 Token 数',
  `thinking_content` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '推理过程内容（enableThinking 时存）',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_session_id` (`session_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 对话消息';

-- Table: ai_model
DROP TABLE IF EXISTS `ai_model`;
CREATE TABLE `ai_model` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `provider_id` bigint(20) NOT NULL COMMENT '关联厂商ID',
  `model_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型名称（如 deepseek-chat）',
  `display_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '显示名称',
  `model_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类型: CHAT/EMBEDDING/RERANK',
  `context_window` int(11) DEFAULT NULL COMMENT '上下文窗口',
  `input_capabilities` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'TEXT' COMMENT '输入能力，逗号分隔',
  `output_capabilities` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'TEXT' COMMENT '输出能力，逗号分隔',
  `api_protocol` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '调用协议',
  `embedding_dimension` int(11) DEFAULT NULL COMMENT '向量维度，仅 EMBEDDING 使用',
  `max_tokens` int(11) DEFAULT '4096' COMMENT '最大输出 Token',
  `temperature` decimal(3,2) DEFAULT '0.70' COMMENT '温度参数',
  `is_default` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '是否默认模型（1是 0否）',
  `status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '1' COMMENT '状态（1正常 0停用）',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  `input_price_per_million` decimal(10,6) DEFAULT NULL COMMENT '输入价格（元/百万Token）',
  `output_price_per_million` decimal(10,6) DEFAULT NULL COMMENT '输出价格（元/百万Token）',
  `currency` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'CNY' COMMENT '币种：CNY/USD',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_provider_id` (`provider_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 模型配置';

-- Table: ai_prompt_template
DROP TABLE IF EXISTS `ai_prompt_template`;
CREATE TABLE `ai_prompt_template` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户ID',
  `template_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板名称',
  `template_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板标识（如 erp_query_agent/erp_report_agent/supervisor）',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板内容（支持 {{variable}} 占位符）',
  `description` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `is_default` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '是否默认模板（1是 0否）',
  `version` int(11) DEFAULT '1' COMMENT '版本号',
  `status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '1' COMMENT '状态（1正常 0停用）',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_template_key` (`template_key`,`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI Prompt 模板';

-- Table: ai_provider
DROP TABLE IF EXISTS `ai_provider`;
CREATE TABLE `ai_provider` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '厂商名称',
  `api_host` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'API 地址',
  `api_key` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'API Key（Jasypt 加密存储）',
  `provider_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '厂商类型: OPENAI/DASHSCOPE/ZHIPU/OLLAMA',
  `status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '1' COMMENT '状态（1正常 0停用）',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 厂商配置';

-- Table: ai_session
DROP TABLE IF EXISTS `ai_session`;
CREATE TABLE `ai_session` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `title` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '会话标题',
  `model_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '使用的模型名称',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  `enabled_tool_ids` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '会话启用的工具ID列表（逗号分隔，null=全部）',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 对话会话';

-- Table: ai_sql_example
DROP TABLE IF EXISTS `ai_sql_example`;
CREATE TABLE `ai_sql_example` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户ID',
  `question` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户问题（自然语言）',
  `sql_template` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SQL 模板（可含 {{variable}} 占位符）',
  `category` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务分类：INVENTORY/SALES/PURCHASE/PRODUCTION/GENERAL',
  `description` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `sort_order` int(11) DEFAULT '0' COMMENT '排序号',
  `status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '1' COMMENT '状态（1正常 0停用）',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_category` (`category`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI SQL Few-Shot 示例';

-- Table: ai_token_usage
DROP TABLE IF EXISTS `ai_token_usage`;
CREATE TABLE `ai_token_usage` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `user_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户名称（冗余，避免关联查询）',
  `model_id` bigint(20) NOT NULL COMMENT '模型ID',
  `model_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型名称（冗余）',
  `usage_date` date NOT NULL COMMENT '统计日期',
  `total_input_tokens` bigint(20) DEFAULT '0' COMMENT '当日输入 Token 总量',
  `total_output_tokens` bigint(20) DEFAULT '0' COMMENT '当日输出 Token 总量',
  `total_tokens` bigint(20) DEFAULT '0' COMMENT '当日 Token 总量（input+output）',
  `request_count` int(11) DEFAULT '0' COMMENT '当日请求次数',
  `total_cost` decimal(12,4) DEFAULT '0.0000' COMMENT '当日总成本（元）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_user_model_date` (`tenant_id`,`user_id`,`model_id`,`usage_date`) USING BTREE,
  KEY `idx_user_date` (`tenant_id`,`user_id`,`usage_date`) USING BTREE,
  KEY `idx_model_date` (`tenant_id`,`model_id`,`usage_date`) USING BTREE,
  KEY `idx_date` (`usage_date`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI Token 用量日统计';

-- Table: ai_tool
DROP TABLE IF EXISTS `ai_tool`;
CREATE TABLE `ai_tool` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `tool_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工具名称（唯一标识，snake_case）',
  `display_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '显示名称',
  `description` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工具描述（AI 理解用途）',
  `tool_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类型: BUILTIN/LOCAL/REMOTE',
  `config_json` text COLLATE utf8mb4_unicode_ci COMMENT '工具配置（JSON 格式，LOCAL/REMOTE 类型使用）',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT '1' COMMENT '状态: 0启用/1停用，默认停用',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_tenant_tool_name` (`tenant_id`,`tool_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='AI 工具配置';

-- Table: app_user_agreement
DROP TABLE IF EXISTS `app_user_agreement`;
CREATE TABLE `app_user_agreement` (
  `id` bigint(20) NOT NULL COMMENT '主键(雪花ID,ASSIGN_ID非自增)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `agreement_key` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '协议标识(privacy_policy/user_service_agreement)',
  `agreement_version` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '协议版本',
  `agree_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '同意时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_user_agreement` (`user_id`,`agreement_key`,`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='App用户协议同意记录';

-- Table: es_seal
DROP TABLE IF EXISTS `es_seal`;
CREATE TABLE `es_seal` (
  `seal_id` bigint(20) NOT NULL COMMENT '印章ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID',
  `seal_type` char(1) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '印章类型(1个人章 2公司章)',
  `seal_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '印章名称',
  `owner_user_id` bigint(20) DEFAULT NULL COMMENT '个人章归属用户ID(公司章为NULL)',
  `seal_oss_id` bigint(20) NOT NULL COMMENT '印章原图OSS ID(私有桶,仅服务端使用)',
  `preview_oss_id` bigint(20) DEFAULT NULL COMMENT '预览图OSS ID(低清+水印,前端可见)',
  `img_width` int(11) NOT NULL COMMENT '印章原图宽(px)',
  `img_height` int(11) NOT NULL COMMENT '印章原图高(px)',
  `status` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '状态(0草稿 1启用 2停用 3销毁)',
  `seal_version` int(11) NOT NULL DEFAULT '1' COMMENT '印章版本(更换章面自增)',
  `valid_from` date DEFAULT NULL COMMENT '生效日期',
  `valid_to` date DEFAULT NULL COMMENT '失效日期',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志(0存在 1删除)',
  PRIMARY KEY (`seal_id`) USING BTREE,
  KEY `idx_es_seal_tenant_type` (`tenant_id`,`seal_type`) USING BTREE,
  KEY `idx_es_seal_owner` (`owner_user_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='电子印章';

-- Table: es_seal_grant
DROP TABLE IF EXISTS `es_seal_grant`;
CREATE TABLE `es_seal_grant` (
  `grant_id` bigint(20) NOT NULL COMMENT '授权ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID',
  `seal_id` bigint(20) NOT NULL COMMENT '印章ID',
  `grantee_user_id` bigint(20) DEFAULT NULL COMMENT '被授权用户ID(用户级授权)',
  `grantee_dept_id` bigint(20) DEFAULT NULL COMMENT '被授权部门ID(部门级授权)',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '限定业务场景(NULL=不限)',
  `can_sign_alone` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '可否单独用章(0否 1是)',
  `valid_from` datetime DEFAULT NULL COMMENT '授权生效时间',
  `valid_to` datetime DEFAULT NULL COMMENT '授权失效时间',
  `status` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '状态(0停用 1启用)',
  `grant_by` bigint(20) DEFAULT NULL COMMENT '授权人用户ID',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志(0存在 1删除)',
  PRIMARY KEY (`grant_id`) USING BTREE,
  KEY `idx_es_grant_seal` (`seal_id`,`status`) USING BTREE,
  KEY `idx_es_grant_user` (`grantee_user_id`,`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='印章使用授权';

-- Table: es_signature
DROP TABLE IF EXISTS `es_signature`;
CREATE TABLE `es_signature` (
  `signature_id` bigint(20) NOT NULL COMMENT '签名ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型',
  `biz_id` bigint(20) DEFAULT NULL COMMENT '业务单据ID',
  `biz_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务单据编号(冗余快照)',
  `signer_user_id` bigint(20) NOT NULL COMMENT '签署人用户ID',
  `signer_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '签署人姓名(冗余快照)',
  `signer_dept_id` bigint(20) DEFAULT NULL COMMENT '签署人部门ID(快照)',
  `seal_id` bigint(20) DEFAULT NULL COMMENT '所用印章ID(逻辑签名可空)',
  `seal_type` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '印章类型快照(1个人 2公司)',
  `signature_meaning` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '签署含义',
  `auth_method` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '认证方式(PASSWORD/SMS/FACE/LOGIN_ONLY)',
  `src_doc_oss_id` bigint(20) DEFAULT NULL COMMENT '签署前文档OSS ID',
  `src_doc_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签署前文档SM3',
  `doc_oss_id` bigint(20) DEFAULT NULL COMMENT '签署后文档OSS ID',
  `doc_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签署后文档SM3',
  `doc_id` bigint(20) DEFAULT NULL COMMENT '关联 es_sign_document.doc_id',
  `signed_at` datetime NOT NULL COMMENT '签署时间(服务端时间)',
  `sign_ip` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签署IP',
  `sign_ua` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签署User-Agent',
  `prev_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前一条链哈希(链首为NULL)',
  `chain_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '本条链哈希(SM3)',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`signature_id`) USING BTREE,
  KEY `idx_es_sig_biz` (`tenant_id`,`biz_type`,`biz_id`) USING BTREE,
  KEY `idx_es_sig_signer` (`signer_user_id`,`signed_at`) USING BTREE,
  KEY `idx_es_sig_chain` (`tenant_id`,`signature_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='电子签名记录(append-only,无更新/删除字段)';

-- Table: es_sign_document
DROP TABLE IF EXISTS `es_sign_document`;
CREATE TABLE `es_sign_document` (
  `doc_id` bigint(20) NOT NULL COMMENT '文档ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型',
  `biz_id` bigint(20) NOT NULL COMMENT '业务单据ID',
  `file_oss_id` bigint(20) NOT NULL COMMENT '正文文件OSS ID(仅PDF)',
  `file_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原始文件名',
  `file_size` bigint(20) DEFAULT NULL COMMENT '文件大小(字节)',
  `file_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '上传时SM3值(验签比对基准)',
  `page_count` int(11) DEFAULT NULL COMMENT 'PDF页数',
  `doc_version` int(11) NOT NULL DEFAULT '1' COMMENT '正文版本',
  `is_current` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '是否当前生效版本(1是 0否)',
  `signed_oss_id` bigint(20) DEFAULT NULL COMMENT '签章后文件OSS ID',
  `sign_status` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '签署状态(0未签 1部分签 2已签)',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志(0存在 1删除)',
  PRIMARY KEY (`doc_id`) USING BTREE,
  KEY `idx_es_doc_biz` (`tenant_id`,`biz_type`,`biz_id`,`is_current`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='待签文档正文';

-- Table: flw_channel_definition
