  UNIQUE KEY `ACT_IDX_EVENT_DEF_UNIQ` (`KEY_`,`VERSION_`,`TENANT_ID_`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci ROW_FORMAT=DYNAMIC;

-- Table: flw_event_deployment
DROP TABLE IF EXISTS `flw_event_deployment`;
CREATE TABLE `flw_event_deployment` (
  `ID_` varchar(255) COLLATE utf8_general_ci NOT NULL,
  `NAME_` varchar(255) COLLATE utf8_general_ci DEFAULT NULL,
  `CATEGORY_` varchar(255) COLLATE utf8_general_ci DEFAULT NULL,
  `DEPLOY_TIME_` datetime(3) DEFAULT NULL,
  `TENANT_ID_` varchar(255) COLLATE utf8_general_ci DEFAULT NULL,
  `PARENT_DEPLOYMENT_ID_` varchar(255) COLLATE utf8_general_ci DEFAULT NULL,
  PRIMARY KEY (`ID_`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci ROW_FORMAT=DYNAMIC;

-- Table: flw_event_resource
DROP TABLE IF EXISTS `flw_event_resource`;
CREATE TABLE `flw_event_resource` (
  `ID_` varchar(255) COLLATE utf8_general_ci NOT NULL,
  `NAME_` varchar(255) COLLATE utf8_general_ci DEFAULT NULL,
  `DEPLOYMENT_ID_` varchar(255) COLLATE utf8_general_ci DEFAULT NULL,
  `RESOURCE_BYTES_` longblob,
  PRIMARY KEY (`ID_`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci ROW_FORMAT=DYNAMIC;

-- Table: flw_ev_databasechangelog
DROP TABLE IF EXISTS `flw_ev_databasechangelog`;
CREATE TABLE `flw_ev_databasechangelog` (
  `ID` varchar(255) COLLATE utf8_general_ci NOT NULL,
  `AUTHOR` varchar(255) COLLATE utf8_general_ci NOT NULL,
  `FILENAME` varchar(255) COLLATE utf8_general_ci NOT NULL,
  `DATEEXECUTED` datetime DEFAULT NULL,
  `ORDEREXECUTED` int(11) NOT NULL,
  `EXECTYPE` varchar(10) COLLATE utf8_general_ci NOT NULL,
  `MD5SUM` varchar(35) COLLATE utf8_general_ci DEFAULT NULL,
  `DESCRIPTION` varchar(255) COLLATE utf8_general_ci DEFAULT NULL,
  `COMMENTS` varchar(255) COLLATE utf8_general_ci DEFAULT NULL,
  `TAG` varchar(255) COLLATE utf8_general_ci DEFAULT NULL,
  `LIQUIBASE` varchar(20) COLLATE utf8_general_ci DEFAULT NULL,
  `CONTEXTS` varchar(255) COLLATE utf8_general_ci DEFAULT NULL,
  `LABELS` varchar(255) COLLATE utf8_general_ci DEFAULT NULL,
