  CONSTRAINT `FLW_FK_BATCH_PART_PARENT` FOREIGN KEY (`BATCH_ID_`) REFERENCES `flw_ru_batch` (`ID_`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_bin ROW_FORMAT=DYNAMIC;

-- Table: gen_table
DROP TABLE IF EXISTS `gen_table`;
CREATE TABLE `gen_table` (
  `table_id` bigint(20) NOT NULL COMMENT '编号',
  `data_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '数据源名称',
  `table_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '表名称',
  `table_comment` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '表描述',
  `sub_table_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联子表的表名',
  `sub_table_fk_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '子表关联的外键名',
  `class_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '实体类名称',
  `tpl_category` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT 'crud' COMMENT '使用的模板（crud单表操作 tree树表操作）',
  `package_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '生成包路径',
  `module_name` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '生成模块名',
  `business_name` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '生成业务名',
  `function_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '生成功能名',
  `function_author` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '生成功能作者',
  `source_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'import' COMMENT '来源类型：import-从数据库导入/design-在线设计',
  `design_id` bigint(20) DEFAULT NULL COMMENT '关联的Online设计ID',
  `design_content` mediumtext COLLATE utf8mb4_unicode_ci COMMENT 'Online设计JSON内容',
  `is_online_form` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '是否启用Online表单：0-否/1-是',
  `gen_type` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '生成代码方式（0zip压缩包 1自定义路径）',
  `gen_path` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT '/' COMMENT '生成路径（不填默认项目路径）',
  `options` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '其它生成选项',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`table_id`) USING BTREE,
  KEY `idx_gen_table_design_id` (`design_id`) USING BTREE,
  KEY `idx_gen_table_source_type` (`source_type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='代码生成业务表';

-- Table: gen_table_column
DROP TABLE IF EXISTS `gen_table_column`;
CREATE TABLE `gen_table_column` (
  `column_id` bigint(20) NOT NULL COMMENT '编号',
  `table_id` bigint(20) DEFAULT NULL COMMENT '归属表编号',
  `column_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '列名称',
  `column_comment` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '列描述',
  `column_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '列类型',
  `java_type` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'JAVA类型',
  `java_field` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'JAVA字段名',
  `is_pk` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否主键（1是）',
  `is_increment` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否自增（1是）',
  `is_required` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否必填（1是）',
  `is_insert` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否为插入字段（1是）',
  `is_edit` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否编辑字段（1是）',
  `is_list` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否列表字段（1是）',
  `is_query` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否查询字段（1是）',
  `query_type` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT 'EQ' COMMENT '查询方式（等于、不等于、大于、小于、范围）',
  `html_type` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '显示类型（文本框、文本域、下拉框、复选框、单选框、日期控件）',
  `dict_type` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '字典类型',
  `form_rules` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '表单验证规则JSON',
  `link_config` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '字段联动配置JSON',
  `form_span` int(11) DEFAULT '24' COMMENT '表单栅格宽度(1-24)',
  `is_readonly` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '是否只读：0-否/1-是',
  `field_tip` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字段提示信息',
  `sort` int(11) DEFAULT NULL COMMENT '排序',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`column_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='代码生成业务表字段';

-- Table: gen_table_design_history
DROP TABLE IF EXISTS `gen_table_design_history`;
CREATE TABLE `gen_table_design_history` (
  `history_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '历史记录ID',
  `table_id` bigint(20) NOT NULL COMMENT '关联的gen_table ID',
  `design_content` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设计JSON内容',
  `version` int(11) DEFAULT '1' COMMENT '版本号',
  `create_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`history_id`) USING BTREE,
  KEY `idx_design_history_table_id` (`table_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='代码生成表设计历史记录';

-- Table: im_conversation_setting
DROP TABLE IF EXISTS `im_conversation_setting`;
CREATE TABLE `im_conversation_setting` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `user_id` bigint(20) NOT NULL COMMENT '所属用户 ID',
  `chat_type` varchar(10) COLLATE utf8mb4_general_ci NOT NULL COMMENT '会话类型: PRIVATE/GROUP',
  `target_id` bigint(20) NOT NULL COMMENT '目标 ID（私聊=对方 userId，群聊=groupId）',
  `is_pinned` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否置顶: 0=否 1=是',
  `pinned_at` datetime(3) DEFAULT NULL COMMENT '置顶时间（用于多会话置顶排序）',
  `is_muted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否免打扰: 0=否 1=是',
  `tenant_id` varchar(20) COLLATE utf8mb4_general_ci DEFAULT '000000' COMMENT '租户编号',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '鍒涘缓閮ㄩ棬',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(3) DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_user_chat_target` (`user_id`,`chat_type`,`target_id`,`tenant_id`) USING BTREE,
  KEY `idx_user_pinned` (`user_id`,`is_pinned`,`pinned_at`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='IM 会话级配置（置顶/免打扰）';

-- Table: im_favorite
DROP TABLE IF EXISTS `im_favorite`;
CREATE TABLE `im_favorite` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `user_id` bigint(20) NOT NULL COMMENT '收藏者用户 ID',
  `message_id` bigint(20) NOT NULL COMMENT '被收藏的消息 ID',
  `chat_type` varchar(10) COLLATE utf8mb4_general_ci NOT NULL COMMENT '来源会话类型: PRIVATE/GROUP',
  `target_id` bigint(20) NOT NULL COMMENT '来源会话目标 ID',
  `from_user_id` bigint(20) DEFAULT NULL COMMENT '消息原发送者（冗余便于列表展示）',
  `msg_type` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '消息类型（冗余）',
  `content_snippet` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '内容摘要（避免列表 JOIN im_message）',
  `tenant_id` varchar(20) COLLATE utf8mb4_general_ci DEFAULT '000000' COMMENT '租户编号',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '鍒涘缓閮ㄩ棬',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '鏇存柊鑰',
  `update_time` datetime(3) DEFAULT NULL COMMENT '鏇存柊鏃堕棿',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_user_message` (`user_id`,`message_id`,`tenant_id`) USING BTREE,
  KEY `idx_user_create` (`user_id`,`create_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='IM 用户收藏消息';

-- Table: im_friend
DROP TABLE IF EXISTS `im_friend`;
CREATE TABLE `im_friend` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `friend_user_id` bigint(20) NOT NULL COMMENT '好友用户ID',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_im_friend` (`tenant_id`,`user_id`,`friend_user_id`) USING BTREE,
  KEY `idx_im_friend_user` (`tenant_id`,`user_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='IM好友关系';

-- Table: im_group
DROP TABLE IF EXISTS `im_group`;
CREATE TABLE `im_group` (
  `group_id` bigint(20) NOT NULL COMMENT '群ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `group_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '群名称',
  `avatar` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '群头像',
  `owner_user_id` bigint(20) NOT NULL COMMENT '群主用户ID',
  `status` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '状态（0正常 1解散）',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`group_id`) USING BTREE,
  KEY `idx_im_group_tenant` (`tenant_id`,`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='IM群组';

-- Table: im_group_member
DROP TABLE IF EXISTS `im_group_member`;
CREATE TABLE `im_group_member` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `group_id` bigint(20) NOT NULL COMMENT '群ID',
  `user_id` bigint(20) NOT NULL COMMENT '成员用户ID',
  `join_time` datetime DEFAULT NULL COMMENT '加入时间',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_group_user` (`group_id`,`user_id`) USING BTREE,
  KEY `idx_igm_user` (`tenant_id`,`user_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='IM群成员';

-- Table: im_message
DROP TABLE IF EXISTS `im_message`;
CREATE TABLE `im_message` (
  `message_id` bigint(20) NOT NULL COMMENT '消息主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `from_user_id` bigint(20) NOT NULL COMMENT '发送人',
  `to_user_id` bigint(20) DEFAULT NULL COMMENT '接收人(私聊)',
  `group_id` bigint(20) DEFAULT NULL COMMENT '群ID(群聊)',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息内容',
  `msg_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'text' COMMENT '消息类型',
  `is_read` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '私聊已读(0否1是)；群聊MVP不使用',
  `revoked` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '是否撤回（0否 1是）',
  `forward_from` bigint(20) DEFAULT NULL COMMENT '杞?彂鏉ユ簮娑堟伅ID',
  `client_msg_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户端消息ID（重发幂等）',
  `mention_user_ids` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '被@的用户ID列表（JSON数组字符串）',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `reply_message_id` bigint(20) DEFAULT NULL COMMENT '引用的消息 ID',
  `reply_snippet` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '引用消息内容摘要',
  PRIMARY KEY (`message_id`) USING BTREE,
  UNIQUE KEY `uk_client_msg_id` (`tenant_id`,`client_msg_id`) USING BTREE,
  KEY `idx_im_msg_private` (`tenant_id`,`from_user_id`,`to_user_id`,`create_time`) USING BTREE,
  KEY `idx_im_msg_to` (`tenant_id`,`to_user_id`,`create_time`) USING BTREE,
  KEY `idx_im_msg_group` (`tenant_id`,`group_id`,`create_time`) USING BTREE,
  KEY `idx_private_unread` (`tenant_id`,`to_user_id`,`is_read`,`from_user_id`,`create_time`) USING BTREE,
  KEY `idx_group_unread` (`tenant_id`,`group_id`,`is_read`) USING BTREE,
  KEY `idx_reply_msg` (`reply_message_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='IM消息';

-- Table: mq_compensation_record
DROP TABLE IF EXISTS `mq_compensation_record`;
CREATE TABLE `mq_compensation_record` (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `message_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联消息ID',
  `business_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型',
  `business_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务ID',
  `compensation_status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '补偿状态: PENDING/SUCCESS/FAILED',
  `compensation_method` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '补偿方法(全限定类名.方法名)',
  `compensation_params` text COLLATE utf8mb4_unicode_ci COMMENT '补偿参数JSON',
  `retry_count` int(11) NOT NULL DEFAULT '0' COMMENT '已重试次数',
  `max_retry` int(11) NOT NULL DEFAULT '5' COMMENT '最大重试次数',
  `next_retry_time` datetime DEFAULT NULL COMMENT '下次重试时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_compensation_status` (`compensation_status`,`next_retry_time`) USING BTREE,
  KEY `idx_business` (`business_type`,`business_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='补偿记录表';

-- Table: mq_dead_letter_record
DROP TABLE IF EXISTS `mq_dead_letter_record`;
CREATE TABLE `mq_dead_letter_record` (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `message_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原始消息ID',
  `exchange` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原始交换机',
  `routing_key` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原始路由键',
  `message_body` text COLLATE utf8mb4_unicode_ci COMMENT '消息体JSON',
  `error_message` text COLLATE utf8mb4_unicode_ci COMMENT '错误信息',
  `retry_count` int(11) NOT NULL DEFAULT '0' COMMENT '已重试次数',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '状态: PENDING/RESOLVED/RESENT',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `message_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '消息类型全限定名(人工重投反序列化用)',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE,
  KEY `idx_create_time` (`create_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='死信记录表';

-- Table: mq_message_record
DROP TABLE IF EXISTS `mq_message_record`;
CREATE TABLE `mq_message_record` (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `message_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息唯一ID',
  `exchange` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '交换机名称',
  `routing_key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '路由键',
  `message_body` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息体JSON',
  `message_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '消息类型全限定名(补偿重投时类型化反序列化用)',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SENDING' COMMENT '状态: SENDING/SENT/CONSUMED/FAILED',
  `retry_count` int(11) NOT NULL DEFAULT '0' COMMENT '重试次数',
  `max_retry` int(11) NOT NULL DEFAULT '3' COMMENT '最大重试次数',
  `next_retry_time` datetime DEFAULT NULL COMMENT '下次重试时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_message_id` (`message_id`) USING BTREE,
  KEY `idx_status_create` (`status`,`create_time`) USING BTREE,
  KEY `idx_next_retry` (`next_retry_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='消息记录表';

-- Table: onl_drag_comp
DROP TABLE IF EXISTS `onl_drag_comp`;
CREATE TABLE `onl_drag_comp` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键',
  `parent_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `comp_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '组件名称',
  `comp_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `icon` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图标',
  `order_num` int(11) DEFAULT NULL COMMENT '排序',
  `type_id` int(11) DEFAULT NULL COMMENT '组件类型',
  `comp_config` longtext COLLATE utf8mb4_unicode_ci COMMENT '组件配置',
  `status` varchar(2) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '状态0:无效 1:有效',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人登录名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人登录名称',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='组件库';

-- Table: onl_drag_dataset_head
DROP TABLE IF EXISTS `onl_drag_dataset_head`;
CREATE TABLE `onl_drag_dataset_head` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'id',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称',
  `code` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '编码',
  `parent_id` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '父id',
  `db_source` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动态数据源',
  `query_sql` varchar(5000) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '查询数据SQL',
  `content` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `iz_agent` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT 'iz_agent',
  `data_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据类型',
  `api_method` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'api方法：get/post',
  `create_time` datetime DEFAULT NULL,
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `low_app_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应用ID',
  `tenant_id` int(10) DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- Table: onl_drag_dataset_item
DROP TABLE IF EXISTS `onl_drag_dataset_item`;
CREATE TABLE `onl_drag_dataset_item` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'id',
  `head_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主表ID',
  `field_name` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字段名',
  `field_txt` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字段文本',
  `field_type` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字段类型',
  `widget_type` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '控件类型',
  `dict_code` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字典Code',
  `dict_table` varchar(125) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dict_text` varchar(125) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `iz_show` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否列表显示',
  `iz_search` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否查询',
  `iz_total` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否计算总计（仅对数值有效）',
  `search_mode` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '查询模式',
  `order_num` int(11) DEFAULT NULL COMMENT '排序',
  `create_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_oddi_head_id` (`head_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- Table: onl_drag_dataset_param
DROP TABLE IF EXISTS `onl_drag_dataset_param`;
CREATE TABLE `onl_drag_dataset_param` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `head_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动态报表ID',
  `param_name` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '参数字段',
  `param_txt` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '参数文本',
  `param_value` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '参数默认值',
  `order_num` int(11) DEFAULT NULL COMMENT '排序',
  `iz_search` int(11) DEFAULT NULL COMMENT '查询标识0否1是 默认0',
  `widget_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '查询控件类型',
  `search_mode` int(11) DEFAULT NULL COMMENT '查询模式1简单2范围',
  `dict_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字典',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人登录名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人登录名称',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_oddp_head_id` (`head_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- Table: onl_drag_page
DROP TABLE IF EXISTS `onl_drag_page`;
CREATE TABLE `onl_drag_page` (
  `id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '界面名称',
  `path` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '访问路径',
  `background_color` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '背景色',
  `background_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '背景图',
  `design_type` int(1) DEFAULT NULL COMMENT '设计模式(1:pc,2:手机,3:平板)',
  `theme` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主题色',
  `style` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '面板主题',
  `cover_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面图',
  `des_json` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '仪表盘主配置JSON',
  `template` longtext COLLATE utf8mb4_unicode_ci COMMENT '布局json',
  `protection_code` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '保护码',
  `type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件夹类',
  `iz_template` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '是否模板(1:是；0不是)',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人登录名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人登录名称',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  `low_app_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应用ID',
  `tenant_id` int(10) DEFAULT NULL COMMENT '租户ID',
  `update_count` int(10) DEFAULT '1',
  `visits_num` int(11) DEFAULT NULL COMMENT '访问次数',
  `del_flag` int(11) DEFAULT NULL COMMENT '删除状态( 0未删除 1已删除)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='可视化拖拽界面';

-- Table: onl_drag_page_comp
DROP TABLE IF EXISTS `onl_drag_page_comp`;
CREATE TABLE `onl_drag_page_comp` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键',
  `parent_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '父组件ID',
  `page_Id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '界面ID',
  `comp_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '组件库ID',
  `component` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '组件名称',
  `config` longtext COLLATE utf8mb4_unicode_ci COMMENT '组件配置',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人登录名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人登录名称',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='可视化拖拽页面组件';

-- Table: onl_drag_share
DROP TABLE IF EXISTS `onl_drag_share`;
CREATE TABLE `onl_drag_share` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键',
  `drag_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '在线仪表盘设计器id',
  `preview_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预览地址',
  `preview_lock` varchar(4) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '密码锁',
  `last_update_time` datetime DEFAULT NULL COMMENT '最后更新时间',
  `term_of_validity` varchar(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '有效期(0:永久有效，1:1天，7:7天)',
  `status` varchar(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否过期(0未过期，1已过期)',
  `preview_lock_status` varchar(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '是否为密码锁(0 否,1是)',
  `share_token` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分享token',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uniq_ods_drag_id` (`drag_id`) USING BTREE COMMENT '仪表盘id唯一索引'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='仪表盘预览分享表';

-- Table: onl_drag_table_relation
DROP TABLE IF EXISTS `onl_drag_table_relation`;
CREATE TABLE `onl_drag_table_relation` (
  `id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键',
  `aggregation_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '聚合表名称',
  `aggregation_desc` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '聚合表描述',
  `relation_forms` longtext COLLATE utf8mb4_unicode_ci COMMENT '关联表单',
  `filter_condition` longtext COLLATE utf8mb4_unicode_ci COMMENT '过滤条件',
  `header_fields` longtext COLLATE utf8mb4_unicode_ci COMMENT '表头字段',
  `calculate_fields` longtext COLLATE utf8mb4_unicode_ci COMMENT '公式字段',
  `validate_info` longtext COLLATE utf8mb4_unicode_ci COMMENT '校验信息',
  `del_flag` tinyint(1) DEFAULT NULL COMMENT '删除状态(0-正常,1-已删除)',
  `low_app_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应用ID',
  `tenant_id` int(11) DEFAULT NULL COMMENT '租户ID',
  `create_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人登录名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建日期',
  `update_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人登录名称',
  `update_time` datetime DEFAULT NULL COMMENT '更新日期',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_aggregation_name` (`aggregation_name`) USING BTREE,
  KEY `idx_del_flag` (`del_flag`) USING BTREE,
  KEY `idx_tenant_id` (`tenant_id`) USING BTREE,
  KEY `idx_create_by` (`create_by`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='仪表盘聚合表';

-- Table: pay_invoice
DROP TABLE IF EXISTS `pay_invoice`;
CREATE TABLE `pay_invoice` (
  `invoice_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '发票ID',
  `order_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单号',
  `invoice_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发票类型',
  `invoice_header` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发票抬头',
  `invoice_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '纳税人识别号',
  `invoice_phone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收票人手机号',
  `invoice_email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收票人邮箱',
  `invoice_remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发票备注',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`invoice_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='发票表';

-- Table: pay_order
DROP TABLE IF EXISTS `pay_order`;
CREATE TABLE `pay_order` (
  `order_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '订单ID',
  `order_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商户订单号',
  `third_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '第三方订单号',
  `order_status` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单状态',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务类型 SO_ORDER/AR_RECEIPT',
  `biz_id` bigint(20) DEFAULT NULL COMMENT '业务单据ID(销售订单ID等)',
  `client_id` bigint(20) DEFAULT NULL COMMENT '客户ID(AR 收款核销用)',
  `total_amount` decimal(18,2) DEFAULT '0.00' COMMENT '璁㈠崟鎬婚噾棰濓紙鍗曚綅锛氬厓锛',
  `actual_amount` decimal(18,2) DEFAULT '0.00' COMMENT '瀹為檯鏀?粯閲戦?锛堝崟浣嶏細鍏冿級',
  `order_content` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单内容',
  `order_message` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '负载信息',
  `pay_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '支付方式',
  `pay_time` datetime DEFAULT NULL COMMENT '支付时间',
  `pay_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '支付人',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`order_id`) USING BTREE,
  KEY `idx_order_number` (`order_number`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='订单表';

-- Table: pu_contract
DROP TABLE IF EXISTS `pu_contract`;
CREATE TABLE `pu_contract` (
  `contract_id` bigint(20) NOT NULL COMMENT '合同ID',
  `contract_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '合同编号',
  `contract_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同名称',
  `vendor_id` bigint(20) DEFAULT NULL COMMENT '供应商ID',
  `vendor_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商编码',
  `vendor_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商名称',
  `contract_type` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同类型',
  `sign_date` datetime DEFAULT NULL COMMENT '签订日期',
  `effective_date` datetime DEFAULT NULL COMMENT '生效日期',
  `expiry_date` datetime DEFAULT NULL COMMENT '失效日期',
  `total_amount` decimal(18,4) DEFAULT NULL COMMENT '合同总金额',
  `currency` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT 'CNY' COMMENT '币种',
  `payment_terms` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '付款条款',
  `status` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT 'DRAFT' COMMENT '合同状态',
  `select_flow_id` bigint(20) DEFAULT NULL COMMENT '审批流程ID',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `attr1` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '扩展字段1',
  `attr2` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '扩展字段2',
  `attr3` bigint(20) DEFAULT NULL COMMENT '扩展字段3',
  `attr4` bigint(20) DEFAULT NULL COMMENT '扩展字段4',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`contract_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='采购合同头表';

-- Table: pu_contract_line
DROP TABLE IF EXISTS `pu_contract_line`;
CREATE TABLE `pu_contract_line` (
  `line_id` bigint(20) NOT NULL COMMENT '行ID',
  `contract_id` bigint(20) NOT NULL COMMENT '合同ID',
  `material_id` bigint(20) DEFAULT NULL COMMENT '物料ID',
  `material_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料编码',
  `material_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料名称',
  `material_spec` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料规格',
  `unit` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '计量单位',
  `unit_price` decimal(18,4) DEFAULT NULL COMMENT '单价',
  `quantity` decimal(18,4) DEFAULT NULL COMMENT '数量',
  `line_amount` decimal(18,4) DEFAULT NULL COMMENT '行金额',
  `delivery_date` datetime DEFAULT NULL COMMENT '交货日期',
  `sort_order` int(11) DEFAULT '0' COMMENT '排序号',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `attr1` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '扩展字段1',
  `attr2` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '扩展字段2',
  `attr3` bigint(20) DEFAULT NULL COMMENT '扩展字段3',
  `attr4` bigint(20) DEFAULT NULL COMMENT '扩展字段4',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`line_id`) USING BTREE,
  KEY `idx_contract_id` (`contract_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='采购合同行表';

-- Table: rep_demo_dxtj
