) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='通知配置';

-- Table: sj_notify_recipient
DROP TABLE IF EXISTS `sj_notify_recipient`;
