  `idempotent_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '幂等id',
  `biz_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '业务编号',
  `executor_name` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '执行器名称',
