-- Table: wf_my_business
DROP TABLE IF EXISTS `wf_my_business`;
CREATE TABLE `wf_my_business` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `create_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `process_definition_key` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流程定义key 一个key会有多个版本的id',
  `process_definition_id` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流程定义id 一个流程定义唯一',
  `process_instance_id` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流程业务实例id 一个流程业务唯一，本表中也唯一',
  `title` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流程业务简要描述',
  `data_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务表id，理论唯一',
  `service_impl_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务类名，用来获取spring容器里的服务对象',
  `proposer` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申请人',
  `act_status` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流程状态说明，有：启动  撤回  驳回  审批中  审批通过  审批异常',
  `task_id` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前的节点定义上的Id,',
  `task_name` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前的节点',
  `task_name_id` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前的节点实例上的Id',
  `todo_users` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前的节点可以处理的用户名',
  `done_users` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理过的人',
  `priority` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前任务节点的优先级 流程定义的时候所填',
  `route_name` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前端页面显示的路由地址',
  `deploy_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流程实例主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户编号',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `dataid` (`data_id`) USING BTREE COMMENT '业务数据Id索引'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='流程业务扩展表';

